def make(n):
    # Produce a handful of realistic names whose length grows with n.
    # Each name contains alphanumerics and occasional '_' or '.'.
    base = []
    for i in range(min(8, max(1, n // 4))):
        # create a name of length roughly n using a simple pattern
        length = max(1, n - i)
        parts = []
        for j in range(length):
            if j % 7 == 0:
                parts.append('_' if (j // 7) % 2 == 0 else '.')
            else:
                # alphanumeric: a‑z, 0‑9
                parts.append(chr(ord('a') + (j % 26)))
        base.append([''.join(parts)])
    return base

